/// <summary>
/// The <c>AVAWHSProcessGuidePromptCoilCalculatorDataStep</c> class represents the step for the calculator data
/// </summary>
[
    ProcessGuideStepName(classStr(AVAWHSProcessGuidePromptCoilCalculatorDataStep))
]
class AVAWHSProcessGuidePromptCoilCalculatorDataStep extends ProcessGuideStep
{
}

Method.Source:
protected final boolean isComplete()
{
    boolean             ret;
    WhsrfPassthrough    pass = controller.parmSessionState().parmPass();

    if (pass.lookupStr(ProcessGuideDataTypeNames::WMSLocationId) != ''
     && pass.lookupStr(ProcessGuideDataTypeNames::ItemId) != ''
     && pass.lookupReal(ProcessGuideDataTypeNames::AVACoilWidth) != 0
     && pass.lookupReal(ProcessGuideDataTypeNames::AVACoilOutsideDiameter) != 0
     && pass.lookupReal(ProcessGuideDataTypeNames::AVACoilInsideDiameter) != 0)
    {

        ret = true;
    }

    return ret;
}
